package ultra.downloads;
import java.util.*;import java.net.*;import java.io.*;import org.json.*;
/** Independent direct-link fallback using the app's own client table, not a bundled extractor. */
public final class PlayerFallback {
 static final String ENDPOINT="https://youtubei.googleapis.com/youtubei/v1/player?prettyPrint=false";
 static final String CLIENT="app.revanced.extension.shared.innertube.client.YouTubeClient$ClientType";
 interface Http{JSONObject post(JSONObject body,Map<String,String> headers)throws Exception;}
 static Http http=new Http(){public JSONObject post(JSONObject body,Map<String,String> headers)throws Exception{
  HttpURLConnection c=(HttpURLConnection)new URL(ENDPOINT).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setDoOutput(true);c.setUseCaches(false);for(Map.Entry<String,String> e:headers.entrySet())c.setRequestProperty(e.getKey(),e.getValue());byte[] data=body.toString().getBytes("UTF-8");c.setFixedLengthStreamingMode(data.length);
  try{try(OutputStream out=c.getOutputStream()){out.write(data);}int code=c.getResponseCode();if(code!=200)throw new IOException("Player HTTP "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))>0){if(out.size()+n>3*1024*1024)throw new IOException("Player response exceeds limit");out.write(b,0,n);}return new JSONObject(new String(out.toByteArray(),"UTF-8"));}}finally{c.disconnect();}
 }};
 static String get(Object c,String getter)throws Exception{Object v=c.getClass().getMethod(getter).invoke(c);return v==null?"":String.valueOf(v);}
 static JSONObject body(Object c,String id,Map<String,String> account)throws Exception{JSONObject client=new JSONObject().put("clientName",get(c,"getClientName")).put("clientVersion",get(c,"getClientVersion")).put("hl","en").put("gl","IN");String[][] optional={{"deviceMake","getDeviceMake"},{"deviceModel","getDeviceModel"},{"osName","getOsName"},{"osVersion","getOsVersion"},{"androidSdkVersion","getAndroidSdkVersion"}};for(String[] f:optional){String value=get(c,f[1]);if(!value.isEmpty())client.put(f[0],f[0].equals("androidSdkVersion")?Integer.parseInt(value):value);}String visitor=account.get("X-Goog-Visitor-Id");if(visitor!=null)client.put("visitorData",visitor);return new JSONObject().put("context",new JSONObject().put("client",client).put("user",new JSONObject().put("lockedSafetyMode",false))).put("videoId",id).put("contentCheckOk",true).put("racyCheckOk",true);}
 static Map<String,String> headers(Object c,Map<String,String> account,boolean auth)throws Exception{Map<String,String> h=new LinkedHashMap<>();h.put("Content-Type","application/json");h.put("User-Agent",get(c,"getUserAgent"));h.put("X-YouTube-Client-Name",get(c,"getId"));h.put("X-YouTube-Client-Version",get(c,"getClientVersion"));for(String k:new String[]{"X-Goog-Visitor-Id","Authorization"}){String v=account.get(k);if(v!=null&&(!k.equals("Authorization")||auth))h.put(k,v);}return h;}
 static boolean allowed(String u){try{URI uri=new URI(u);String h=uri.getHost();return "https".equals(uri.getScheme())&&h!=null&&(h.equals("googlevideo.com")||h.endsWith(".googlevideo.com"))&&uri.getUserInfo()==null;}catch(Exception e){return false;}}
 static Hooks.Audio select(JSONObject response,String id,String required,String quality,String agent)throws Exception{JSONObject vd=response.optJSONObject("videoDetails");if(vd!=null&&!vd.optString("videoId",id).equals(id))throw new IOException("Player returned a different video");JSONObject ps=response.optJSONObject("playabilityStatus");if(ps!=null&&!"OK".equals(ps.optString("status")))throw new IOException("Player status "+ps.optString("status","unknown"));JSONObject sd=response.optJSONObject("streamingData");if(sd==null)return null;JSONArray formats=sd.optJSONArray("adaptiveFormats");if(formats==null)return null;Hooks.Audio best=null;long score=Long.MIN_VALUE;
  for(int i=0;i<formats.length();i++){JSONObject f=formats.optJSONObject(i);if(f==null||f.has("drmFamilies")||f.has("licenseInfos"))continue;String mime=f.optString("mimeType"),url=f.optString("url");int rate=f.optInt("bitrate");String key=f.optInt("itag")+":"+f.optLong("lastModified");if(!mime.startsWith("audio/")||!allowed(url)||rate<=0||required!=null&&!required.equals(key))continue;try{String expire=android.net.Uri.parse(url).getQueryParameter("expire");if(expire!=null&&Long.parseLong(expire)*1000L<System.currentTimeMillis()+30000)continue;}catch(NumberFormatException ignored){}long rank="saver".equals(quality)?-rate:rate;if("aac".equals(quality)&&mime.startsWith("audio/mp4"))rank+=10000000;if(best==null||rank>score){best=new Hooks.Audio();best.url=url;best.mime=mime;best.key=key;best.bitrate=rate;best.size=f.optLong("contentLength");best.agent=agent;score=rank;}}
 return best;
 }
 public static final class Spec{
  final String name,version,make,model,os,osVersion,sdk,ua;final int id;
  Spec(String n,String v,int id,String make,String model,String os,String osv,String sdk,String ua){name=n;version=v;this.id=id;this.make=make;this.model=model;this.os=os;osVersion=osv;this.sdk=sdk;this.ua=ua;}
  public String getClientName(){return name;}public String getClientVersion(){return version;}public int getId(){return id;}public String getDeviceMake(){return make;}public String getDeviceModel(){return model;}public String getOsName(){return os;}public String getOsVersion(){return osVersion;}public String getAndroidSdkVersion(){return sdk;}public String getUserAgent(){return ua;}
 }
 // Current Ultra source profiles. No public-extractor or third-party pipeline code is bundled.
 static final Object[] ULTRA={new Spec("ANDROID_VR","1.65.10",28,"Oculus","Quest 3","Android","12L","32","com.google.android.apps.youtube.vr.oculus/1.65.10 (Linux; U; Android 12L; eureka-user Build/SQ3A.220605.009.A1) gzip"),new Spec("VISIONOS","1.02",101,"Apple","RealityDevice14,1","visionOS","26.6.1","","com.google.visionosyoutube/1.02 (RealityDevice14,1; U; CPU visionOS 26_6_1 like Mac OS X; en_US) gzip"),new Spec("IOS","20.10.4",5,"Apple","iPhone16,2","iPhone","18.3.2.22D82","","com.google.ios.youtube/20.10.4 (iPhone16,2; U; CPU iOS 18_3_2 like Mac OS X;)"),new Spec("ANDROID","20.10.38",3,"","","Android","11","30","com.google.android.youtube/20.10.38 (Linux; U; Android 11) gzip")};
 static Hooks.Audio resolve(String id,String required,String quality,List<String> errors){long deadline=System.currentTimeMillis()+35000;Map<String,String> account=NativeStreams.requestHeaders();List<Object> clients=new ArrayList<>(Arrays.asList(ULTRA));try{Class<?> type=Class.forName(CLIENT);clients.addAll(Arrays.asList((Object[])type.getMethod("values").invoke(null)));}catch(Throwable e){errors.add("fallback-client-table: "+ResolveErrors.describe(e));}
  Set<String> seen=new HashSet<>();for(Object c:clients){try{String name=get(c,"getClientName"),version=get(c,"getClientVersion");if(!Arrays.asList("ANDROID_VR","VISIONOS","ANDROID","IOS").contains(name)||!seen.add(name+":"+version))continue;for(boolean useAuth:new boolean[]{true,false}){if(useAuth&&!account.containsKey("Authorization"))continue;if(System.currentTimeMillis()>deadline)return null;try{Hooks.Audio a=select(http.post(body(c,id,account),headers(c,account,useAuth)),id,required,quality,get(c,"getUserAgent"));if(a!=null){Hooks.usable(a);Diagnostics.event("stream_resolve","direct-player-fallback");return a;}errors.add("direct-"+name.toLowerCase(Locale.US)+(useAuth?"-account":"-guest")+": no direct audio");}catch(Exception e){errors.add("direct-"+name.toLowerCase(Locale.US)+(useAuth?"-account":"-guest")+": "+ResolveErrors.describe(e));}}}catch(Exception e){errors.add("fallback-client: "+ResolveErrors.describe(e));}}return null;}
}
